`owner_user_id` int NOT NULL DEFAULT '0' COMMENT '所属用户id',
`gongzitiaojiegou` int DEFAULT NULL COMMENT '工资条结构',
`jibengongzi` decimal(10,2) DEFAULT NULL COMMENT '基本工资',
